(SELECT case when category_code=1 and device_type=400600020003 then 2 when category_code=2 and device_type=40084401 then 1 when category_code=2 and device_type=40084403 then 4 when category_code=2 and device_type=40084402 then 5 else null end as deviceType, COALESCE(SUM(CASE WHEN device_status = 0 THEN 1 ELSE 0 END), 0) as onlineCount, COALESCE(COUNT(*), 0) as totalCount, CASE WHEN COUNT(*) > 0 THEN ROUND(SUM(CASE WHEN device_status = 0 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) ELSE 0.0 END as onlineRate FROM vm_iot_device_t WHERE delete_flag = 0
GROUP BY deviceType HAVING deviceType IS NOT NULL) union ( select 3 as deviceType, COALESCE(SUM(CASE WHEN device_status = 0 THEN 1 ELSE 0 END), 0) as onlineCount, COALESCE(COUNT(*), 0) as totalCount, CASE WHEN COUNT(*) > 0 THEN ROUND(SUM(CASE WHEN device_status = 0 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) ELSE 0.0 END as onlineRate from vm_device_info_t where delete_flag ='0'
AND device_code in
#{item}
AND 1 = 0
)

